using System.Runtime.InteropServices;
using RibbonKit.WinForms;

namespace RibbonKitDesignerConsumer;

internal static class OptionsTreeCheck
{
    internal static void Verify(string output)
    {
        Directory.CreateDirectory(output); var evidence = new List<string>();
        foreach (var family in new[] { RibbonBuiltInTheme.Office2019Light, RibbonBuiltInTheme.Office2024Light })
        foreach (var backdrop in new[] { RibbonWindowBackdrop.None, RibbonWindowBackdrop.Mica })
        {
            var icon = new ProbeIcon(); using var renderer = new ProbeRenderer(); using var owner = new RibbonForm { StartPosition = FormStartPosition.Manual, Bounds = new(-16000, -16000, 1200, 700), ShowInTaskbar = false, Backdrop = backdrop }; using var ribbon = new RibbonControl { BuiltInTheme = family, Renderer = renderer, AnimationLevel = RibbonAnimationLevel.None }; owner.Controls.Add(ribbon); owner.Ribbon = ribbon;
            for (int i = 0; i < 2; i++) { var tab = new RibbonTab { Id = "tab" + i, Text = "Tab " + i }; var group = new RibbonGroup { Id = "group" + i, Text = "Group " + i, Icon = icon }; group.Items.Add(new RibbonButtonItem { Id = "save" + i, Text = "Save " + i, Icon = icon }); tab.Groups.Add(group); ribbon.Tabs.Add(tab); } ribbon.CommandCatalog.CaptureDefaults(); owner.Show(); Application.DoEvents(); var original = ribbon.Theme; string scope = family + "-" + backdrop; int states = 0;
            var appearance = new RibbonOptionsAppearanceSettings { TreeCornerRadius = 9, TreeSelectedBackground = new(Color.LightBlue, Color.LightGreen), TreeCheckSize = 12, TreeIconSize = 10, TreeIconTextGap = 4, TreeFocusInset = 5, RowIconSize = 16, FrameBorderWidth = 3, NavigationCornerRadius = 12 };
            foreach (var density in new[] { RibbonDensity.Compact, RibbonDensity.Touch })
            {
                ribbon.Density = density; ribbon.Theme = original with { OptionsAppearance = appearance, Chevrons = new() { Length = 20, Depth = 10, StrokeWidth = 2.5 } }; using var dialog = new RibbonQuickAccessCustomizationForm(ribbon, "RibbonKit.Tree.Check") { StartPosition = FormStartPosition.Manual, Location = new(-16000, -16000), ShowInTaskbar = false }; dialog.SelectedPage = dialog.Pages.First(p => p.Name != "QuickAccessOptionsPage"); dialog.Show(owner); Application.DoEvents(); var tree = Descendants(dialog.RibbonEditor).OfType<TreeView>().Single(); var root = tree.Nodes[0]; tree.SelectedNode = root; root.ExpandAll(); dialog.Activate(); tree.Focus(); var handle = tree.Handle; var parent = tree.Parent; var bounds = tree.Bounds; int height = tree.ItemHeight, indent = tree.Indent; var textBounds = root.Bounds; var draft = dialog.RibbonEditor.Session.Draft; var nodes = All(tree.Nodes).ToArray(); icon.Bounds.Clear(); renderer.Checks.Clear(); renderer.Texts = 0;
                using (var image = Print(tree)) { Require(icon.Bounds.Count > 0 && icon.Bounds.All(b => b.Width == S(10, tree.DeviceDpi)), "Actual tree icons bypassed authored slots."); Require(renderer.Checks.Count == 2 && renderer.Checks.All(c => c.Bounds.Width == S(12, tree.DeviceDpi)), "Actual indicator hooks bypassed tree check size."); Require(renderer.Texts == 0, "Tree text was rerouted through a renderer hook."); Require(image.GetPixel(tree.Width - 2, root.Bounds.Top + height / 2).ToArgb() != ribbon.Theme.Surface.ToArgb(), "Selected native tree row lost authored fill."); image.Save(Path.Combine(output, scope + "-" + density + "-tree.png")); }
                var checkbox = renderer.Checks.First().Bounds; var checkPoint = new Point(checkbox.Left + checkbox.Width / 2, checkbox.Top + checkbox.Height / 2); ribbon.Theme = ribbon.Theme with { OptionsAppearance = appearance with { TreeCheckSize = 0, TreeIconSize = 0, TreeSelectedBackground = new(Color.Transparent) }, Chevrons = new() { StrokeWidth = 0 } }; icon.Bounds.Clear(); renderer.Checks.Clear(); using (var image = Print(tree)) { Require(icon.Bounds.Count == 0 && renderer.Checks.Count == 0, "Zero tree glyph sizes did not hide paint."); Require(image.GetPixel(tree.Width - 2, root.Bounds.Top + height / 2).ToArgb() == ribbon.Theme.Surface.ToArgb(), "Transparent tree fill did not reveal Surface."); }
                Click(tree, checkPoint); Require(root.StateImageIndex == 0 && dialog.RibbonEditor.Session.Draft.Ribbon!.Tabs[0].Visible == false && ribbon.Tabs[0].Visible, "Hidden check target lost its isolated single toggle."); SendMessage(tree.Handle, 0x100, 0x20, 0); SendMessage(tree.Handle, 0x101, 0x20, 0); Require(root.StateImageIndex == 1 && dialog.RibbonEditor.Session.Draft.Ribbon!.Tabs[0].Visible, "Native Space did not retain the tree checkbox contract.");
                int collapsed = 0; tree.AfterCollapse += (_, e) => { if (ReferenceEquals(e.Node, root)) collapsed++; }; var expandPoint = new Point(indent / 2, root.Bounds.Top + height / 2); SendPoint(tree, 0x201, expandPoint); SendPoint(tree, 0x203, expandPoint); SendPoint(tree, 0x202, expandPoint); Require(!root.IsExpanded && collapsed == 1, "Hidden expander target toggled more than once."); Click(tree, expandPoint); Require(root.IsExpanded, "Hidden expander target could not reopen.");
                Require(tree.Handle == handle && ReferenceEquals(parent, tree.Parent) && tree.Bounds == bounds && tree.ItemHeight == height && tree.Indent == indent && root.Bounds == textBounds && nodes.SequenceEqual(All(tree.Nodes)) && ReferenceEquals(draft, dialog.RibbonEditor.Session.Draft), "Tree decoration replaced native nodes, targets, handle or draft."); Click(tree, checkPoint); Require(!dialog.RibbonEditor.Session.Draft.Ribbon!.Tabs[0].Visible && ribbon.Tabs[0].Visible, "Pending tree visibility edit changed live sources."); ribbon.Theme = original; using (var reset = Print(tree)) reset.Save(Path.Combine(output, scope + "-" + density + "-reset.png")); Require(tree.Handle == handle && tree.SelectedNode == root, "Reset replaced native tree ownership."); Descendants(dialog).OfType<Button>().Single(b => b.Name == "CancelCustomization").PerformClick(); Require(ribbon.Tabs[0].Visible && nodes.All(n => n.TreeView is null || ReferenceEquals(n.TreeView, tree)), "Cancel applied the tree draft or moved a node."); states++;
            }
            ribbon.Theme = original with { OptionsAppearance = appearance with { TreeCornerRadius = null, TreeSelectedBackground = null, TreeCheckSize = null, TreeIconSize = null, TreeIconTextGap = null, TreeFocusInset = null } }; Require(ribbon.Theme.OptionsAppearance is { RowIconSize: 16, FrameBorderWidth: 3, NavigationCornerRadius: 12 }, "Tree Reset cleared accepted list/frame/navigation roles."); ribbon.Theme = ribbon.Theme with { OptionsAppearance = null }; Require(ribbon.Theme.OptionsAppearance is null, "Whole-group Reset failed."); evidence.Add($"PASS {scope}: effective owner={owner.EffectiveBackdrop}, dpi={ribbon.DeviceDpi}; {states} densities; actual tree/check/icon paint and direct native text, zero/Transparent hide, hidden check/expand targets and Space, exactly-one double-click toggle, retained HWND/parent/nodes/text bounds/indent/row height/draft, pending edit/Cancel and partial/group Reset."); owner.Close();
        }
        using (var demo = new DesignerForm()) demo.VerifyOptionsTreeDemo(output);
        evidence.Add("PASS demo: three new tree groups on Theme effects 9, six total, earlier three row groups retained. Tab 8 retains five, tabs 1-7 retain seven/five/four/seven/six/three/eight. Public presets/hide/independent/shared-chevron resets, isolated public-model tree preview, real ribbon mode/sources and idempotence pass."); evidence.Add("Synchronous offscreen public-package checks at actual 120 DPI. Physical input/IME, actual VS, external UIA, mixed-monitor and visible pacing remain separate. Tree decoration fits existing slots; shared Chevrons affects other utilities. Icon-picker tiles and caption/title remain separate."); File.WriteAllLines(Path.Combine(output, "result.log"), evidence);
    }
    private static int S(int n, int dpi) => (int)Math.Round(n * dpi / 96d);
    private static void Click(Control c, Point p) { SendPoint(c, 0x201, p); SendPoint(c, 0x202, p); }
    private static void SendPoint(Control c, int message, Point p) => SendMessage(c.Handle, message, 0, (nint)((p.Y << 16) | (p.X & 0xffff)));
    [DllImport("user32.dll")] private static extern nint SendMessage(nint window, int message, nint wParam, nint lParam);
    private static Bitmap Print(Control c) { var image = new Bitmap(c.Width, c.Height); c.DrawToBitmap(image, new(Point.Empty, image.Size)); return image; }
    private static IEnumerable<Control> Descendants(Control root) => root.Controls.Cast<Control>().SelectMany(c => new[] { c }.Concat(Descendants(c)));
    private static IEnumerable<TreeNode> All(TreeNodeCollection nodes) => nodes.Cast<TreeNode>().SelectMany(n => new[] { n }.Concat(All(n.Nodes)));
    private static void Require(bool condition, string message) { if (!condition) throw new InvalidOperationException(message); }
    private sealed class ProbeIcon : IRibbonIcon { internal readonly List<Rectangle> Bounds = []; public void Draw(Graphics g, Rectangle b, RibbonIconContext c) { Bounds.Add(b); using var ink = new SolidBrush(c.Foreground); g.FillRectangle(ink, b); } }
    private sealed class ProbeRenderer : RibbonOffice2024Renderer { internal readonly List<(Rectangle Bounds, bool Checked)> Checks = []; internal int Texts; public override void DrawCheckBoxIndicator(RibbonPaintContext c, RibbonCheckBoxItem item) { Checks.Add((c.Bounds, item.Checked)); base.DrawCheckBoxIndicator(c, item); } public override void DrawText(RibbonPaintContext c, string text, Color color, TextFormatFlags flags) { Texts++; base.DrawText(c, text, color, flags); } }
}
